window.bookSummaryJSON = "<p>Edinburgh, 1920. Seizing upon the possibility of a reunion with his closest comrade from the trenches, Dorian arrives in the capital city of Scotland on Halloween! Guisers are out in force, disapproving gentlemen walk the streets...and a sinister department store has a great deal more on offer than it might initially advertise. </p><p><b>Note: <i>The Confessions of Dorian Gray</i> contains adult material and is not suitable for younger listeners. </b></p>"; 
